SELECT LISTAGG(ym||'|'||hs||'|'||inn||'|'||ar,'~') WITHIN GROUP (ORDER BY ym) r, COUNT(*) n FROM (SELECT TO_CHAR(t.VM_DATE,'YYYYMM') ym, ROUND(SUM(CASE WHEN t.SUB_SYSTEM_CODE NOT IN ('AR','IN') THEN t.CR_AMOUNT-t.DR_AMOUNT ELSE 0 END),2) hs, ROUND(SUM(CASE WHEN t.SUB_SYSTEM_CODE='IN' THEN t.CR_AMOUNT-t.DR_AMOUNT ELSE 0 END),2) inn, ROUND(SUM(CASE WHEN t.SUB_SYSTEM_CODE='AR' THEN t.CR_AMOUNT-t.DR_AMOUNT ELSE 0 END),2) ar FROM {P}GL_TRANSACTIONS_DETAILS t WHERE t.STATUS<>'C' AND t.VM_TYPE='S' AND (t.ACCOUNT_NO LIKE '41%' OR t.ACCOUNT_NO LIKE '42%') AND t.VM_DATE>=DATE '2023-01-01' GROUP BY TO_CHAR(t.VM_DATE,'YYYYMM'))
